function EvidenceBoard() {
  const [query, setQuery] = useState("");
  const [cat, setCat] = useState("All");
  const [active, setActive] = useState(null);

  const results = useMemo(() => {
    const q = query.trim().toLowerCase();
    return CASE_FILES.filter((f) => {
      const matchCat = cat === "All" || f.category === cat;
      if (!matchCat) return false;
      if (!q) return true;
      const hay = [
        f.id,
        f.title,
        f.alt || "",
        f.thesis,
        f.summary,
        f.category,
        ...(f.evidence || []),
      ]
        .join(" ")
        .toLowerCase();
      return hay.includes(q);
    });
  }, [query, cat]);

  useEffect(() => {
    function onKey(e) {
      if (e.key === "Escape") setActive(null);
    }
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  return (
    <section className="sh-board">
      <div className="sh-section">
        <div className="sh-eyebrow">Evidence Board &mdash; Open Record</div>
        <div className="sh-board-head">
          <h2>The Case Files</h2>
          <div className="count">
            {results.length} OF {CASE_FILES.length} FILES SHOWN
          </div>
        </div>

        <div className="sh-controls">
          <div className="sh-search">
            <SearchIcon />
            <input
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Search files, theses, evidence, sources…"
            />
          </div>
        </div>
        <div className="sh-filters" style={{ marginBottom: 30 }}>
          {CATEGORIES.map((c) => (
            <button
              key={c}
              className={"sh-chip" + (cat === c ? " on" : "")}
              onClick={() => setCat(c)}
            >
              {c}
            </button>
          ))}
        </div>

        {results.length === 0 ? (
          <div className="sh-empty">// NO MATCHING RECORDS // ADJUST SEARCH OR FILTER //</div>
        ) : (
          <div className="sh-grid">
            {results.map((f) => (
              <article key={f.id} className="sh-card" onClick={() => setActive(f)}>
                <div className="cf-top">
                  <span className="cf-id">FILE {f.id}</span>
                  <span className="cf-cat">{f.category}</span>
                </div>
                <h3>{f.title}</h3>
                {f.alt && <div className="alt">a.k.a. {f.alt}</div>}
                <p className="thesis">{f.thesis}</p>
                <p className="sum">{f.summary}</p>
                {f.evidence && (
                  <div className="ev">
                    {f.evidence.map((e) => (
                      <span key={e}>{e}</span>
                    ))}
                  </div>
                )}
              </article>
            ))}
          </div>
        )}

        {/* Reference archive */}
        <div className="sh-ref">
          <SealMark className="seal" />
          <div>
            <div style={{ fontFamily: "var(--mono)", fontSize: 10, letterSpacing: 2, color: "var(--oxblood)", marginBottom: 6 }}>
              REFERENCE VOLUME &mdash; NOT AN ARGUMENT
            </div>
            <h3>{REFERENCE.title}</h3>
            <p className="thesis">{REFERENCE.thesis}</p>
            <p>{REFERENCE.summary}</p>
          </div>
        </div>
      </div>

      {active && (
        <div className="sh-modal-bg" onClick={() => setActive(null)}>
          <div className="sh-modal" onClick={(e) => e.stopPropagation()}>
            <div className="sh-modal-head">
              <button className="sh-modal-close" onClick={() => setActive(null)}>
                &times;
              </button>
              <div className="cf-id">FILE {active.id} &middot; {active.category}</div>
              <h3>{active.title}</h3>
              {active.alt && <div className="alt">a.k.a. {active.alt}</div>}
            </div>
            <div className="sh-modal-body">
              <p className="thesis">{active.thesis}</p>
              <p className="sum">{active.summary}</p>
              {active.evidence && (
                <>
                  <h5>Documented Evidence</h5>
                  <div className="ev">
                    {active.evidence.map((e) => (
                      <span key={e}>{e}</span>
                    ))}
                  </div>
                </>
              )}
            </div>
          </div>
        </div>
      )}
    </section>
  );
}

function Contact() {
  const [form, setForm] = useState({ name: "", email: "", topic: "General", message: "" });
  const [sent, setSent] = useState(false);

  // FOIA generator
  const [foia, setFoia] = useState({ agency: "", officer: "", records: "", interest: "" });
  const [foiaText, setFoiaText] = useState("");
  const [copied, setCopied] = useState(false);

  function buildFoia() {
    const today = new Date().toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric" });
    const interest =
      foia.interest.trim() ||
      "The requested records concern documented government conduct of substantial public concern. As an independent journalist publishing political analysis, I will make the records available to the public through publication, in keeping with the journalistic function the Freedom of Information Act was designed to serve.";
    const txt = `${today}

${foia.officer.trim() || "FOIA Officer"}
${foia.agency.trim() || "[Agency FOIA Office]"}

RE: Freedom of Information Act Request

Dear FOIA Officer:

Pursuant to the Freedom of Information Act, 5 U.S.C. § 552, I hereby request copies of the following records:

${foia.records.trim() || "[Describe the records with specificity — dates, names, titles, file numbers, programs, date ranges.]"}

I request that all responsive records be provided in electronic format if available.

SEARCH METHODOLOGY. I request that the agency conduct a reasonable search of all systems of records likely to contain responsive documents, and provide a brief description of the systems searched and the search terms used.

FEE WAIVER REQUEST. I request a waiver of all fees pursuant to 5 U.S.C. § 552(a)(4)(A)(iii). Disclosure is in the public interest and is not primarily in my commercial interest. Specifically: ${interest}

NEWS MEDIA STATUS. If the fee waiver is denied, I assert news media status under 5 U.S.C. § 552(a)(4)(A)(ii)(II) as an independent journalist engaged in regular publication of news and analysis to the public.

SEGREGABILITY. Should any records be deemed exempt, I request release of all reasonably segregable non-exempt portions, with a Vaughn-type index identifying each exemption claimed under 5 U.S.C. § 552(b).

STATUTORY RESPONSE TIME. I note that 5 U.S.C. § 552(a)(6)(A)(i) requires a determination within twenty (20) business days. Please confirm receipt and provide an estimated completion date.

I look forward to your response within the statutory timeframe.

Sincerely,
[Your Name]
Independent Journalist`;
    setFoiaText(txt);
    setCopied(false);
  }

  function copyFoia() {
    if (!foiaText) return;
    try {
      const ta = document.createElement("textarea");
      ta.value = foiaText;
      document.body.appendChild(ta);
      ta.select();
      document.execCommand("copy");
      document.body.removeChild(ta);
      setCopied(true);
    } catch (e) {
      setCopied(false);
    }
  }

  return (
    <section className="sh-contact">
      <div className="sh-section">
        <div className="sh-contact-hero">
          <div className="sh-eyebrow">Contact &mdash; FOIA &mdash; Civic Action</div>
          <h2>Build the Record. Apply the Pressure.</h2>
          <p>
            Diagnosis without action is just despair with footnotes. Use these mechanisms. They are
            legal, they are public, and they accumulate the way debt does &mdash; only in the other
            direction.
          </p>
        </div>

        {/* Action grid */}
        <div className="sh-action-grid">
          <div className="sh-action">
            <div className="tag">Federal Records</div>
            <h4>File a FOIA Request</h4>
            <p>
              The Freedom of Information Act exists for exactly this. What an agency releases tells
              you something. What it refuses to release tells you more.
            </p>
            <a href="https://www.foia.gov" target="_blank" rel="noopener noreferrer">
              foia.gov &rarr;
            </a>
          </div>
          <div className="sh-action">
            <div className="tag">The Money Trail</div>
            <h4>Follow the Contributions</h4>
            <p>
              Look up your representative's industry contributions and cross-reference them against
              their votes. The correlation requires no interpretation.
            </p>
            <a href="https://www.opensecrets.org" target="_blank" rel="noopener noreferrer">
              opensecrets.org &rarr;
            </a>
          </div>
          <div className="sh-action">
            <div className="tag">Your Officials</div>
            <h4>Write &mdash; Federal &amp; State</h4>
            <p>
              Ready-made constituent letters covering Medicare negotiation, the DoD audit, FISA 702,
              declassification, and state-level reform. Demand a substantive reply, not a form letter.
            </p>
            <ul>
              <li>Find your U.S. House rep &amp; senators</li>
              <li>Find your state legislators</li>
              <li>Call &mdash; don't email. Record the answer.</li>
            </ul>
            <a href="https://www.congress.gov/members/find-your-member" target="_blank" rel="noopener noreferrer">
              find your member &rarr;
            </a>
          </div>
          <div className="sh-action">
            <div className="tag">Classified Holdings</div>
            <h4>Mandatory Declassification Review</h4>
            <p>
              A separate, parallel track from FOIA under Executive Order 13526 &mdash; it can succeed
              where FOIA fails, especially for records over 25 years old.
            </p>
            <a href="https://www.archives.gov/declassification" target="_blank" rel="noopener noreferrer">
              archives.gov &rarr;
            </a>
          </div>
        </div>

        {/* FOIA generator */}
        <div className="sh-form" style={{ marginBottom: 40 }}>
          <h3>FOIA Request Generator</h3>
          <p className="sub">
            Fill in the fields. The statutory language &mdash; fee waiver, news-media status,
            segregability, response clock &mdash; is built in and calibrated to preempt the most common
            agency delay tactics.
          </p>
          <div className="sh-form-row">
            <div className="sh-field">
              <label>Agency FOIA Office</label>
              <input
                value={foia.agency}
                onChange={(e) => setFoia({ ...foia, agency: e.target.value })}
                placeholder="e.g. FBI Record/Information Dissemination Section"
              />
            </div>
            <div className="sh-field">
              <label>FOIA Officer (if known)</label>
              <input
                value={foia.officer}
                onChange={(e) => setFoia({ ...foia, officer: e.target.value })}
                placeholder="FOIA Officer"
              />
            </div>
          </div>
          <div className="sh-field">
            <label>Records Requested (be specific)</label>
            <textarea
              value={foia.records}
              onChange={(e) => setFoia({ ...foia, records: e.target.value })}
              placeholder="Name the event with date, the individual with identifiers, or the program with a date range. Specific requests force production or a specific exemption."
            />
          </div>
          <div className="sh-field">
            <label>Public-Interest Justification (optional &mdash; default provided)</label>
            <textarea
              value={foia.interest}
              onChange={(e) => setFoia({ ...foia, interest: e.target.value })}
              placeholder="Leave blank to use the standard journalist / public-interest justification."
              style={{ minHeight: 80 }}
            />
          </div>
          <button className="sh-btn sh-btn-gold" onClick={buildFoia}>
            Generate Request
          </button>
          {foiaText && (
            <>
              <div className="sh-foia-out">{foiaText}</div>
              <button className="sh-btn sh-btn-ghost sh-copy" onClick={copyFoia}>
                {copied ? "Copied ✓" : "Copy to Clipboard"}
              </button>
            </>
          )}
        </div>

        {/* Direct contact */}
        <div className="sh-form">
          <h3>Contact the Project</h3>
          <p className="sub">
            Tips, corrections, source documents, collaboration. Corrections are taken seriously and
            acknowledged plainly.
          </p>
          {!sent ? (
            <form
              onSubmit={(e) => {
                e.preventDefault();
                setSent(true);
              }}
            >
              <div className="sh-form-row">
                <div className="sh-field">
                  <label>Name / Handle</label>
                  <input
                    value={form.name}
                    onChange={(e) => setForm({ ...form, name: e.target.value })}
                    required
                  />
                </div>
                <div className="sh-field">
                  <label>Email</label>
                  <input
                    type="email"
                    value={form.email}
                    onChange={(e) => setForm({ ...form, email: e.target.value })}
                    required
                  />
                </div>
              </div>
              <div className="sh-field">
                <label>Subject</label>
                <select
                  value={form.topic}
                  onChange={(e) => setForm({ ...form, topic: e.target.value })}
                >
                  <option>General</option>
                  <option>Tip / Source Document</option>
                  <option>Correction</option>
                  <option>FOIA Collaboration</option>
                  <option>Press / Republication</option>
                </select>
              </div>
              <div className="sh-field">
                <label>Message</label>
                <textarea
                  value={form.message}
                  onChange={(e) => setForm({ ...form, message: e.target.value })}
                  required
                />
              </div>
              <button className="sh-btn sh-btn-gold" type="submit">
                Transmit
              </button>
            </form>
          ) : (
            <div className="sh-sent">
              // MESSAGE LOGGED // This demo form does not send mail — wire it to your inbox or a
              form service (Formspree, your own endpoint) before publishing.
            </div>
          )}
        </div>
      </div>
    </section>
  );
}

